include "globals.mzn";

% Decision variables: each digit is 0..9, but a cannot be 0 (since ab is a two-digit number)
var 1..9: a;
var 0..9: b;
var 0..9: c;
var 0..9: d;

% All digits must be different
constraint all_different([a, b, c, d]);

% The 2-digit number cd is 3 times the 2-digit number ab
constraint (c * 10 + d) = 3 * (a * 10 + b);

% The 2-digit number da is 2 times the 2-digit number bc
constraint (d * 10 + a) = 2 * (b * 10 + c);

solve satisfy;

output [
    "{",
    join(",", [
        "\"a\": " ++ show(a),
        "\"b\": " ++ show(b),
        "\"c\": " ++ show(c),
        "\"d\": " ++ show(d)
    ]),
    "}"
];
```

