% Include the global constraints library
include "globals.mzn";

% Problem parameters
int: n = 20; % total number of steps
set of int: Moves = 1..n;
set of int: StepSizes = 3..5; % allowed step sizes

% Decision variables
array[Moves] of var 0..5: steps; % steps taken at each move (0 if not used)

% Constraints

% Each move is either 0 (not used) or one of the allowed step sizes
constraint forall(i in Moves) (
    steps[i] = 0 \/ steps[i] = 3 \/ steps[i] = 4 \/ steps[i] = 5
);

% The sum of all steps taken must be exactly n
constraint sum(i in Moves)(steps[i]) = n;

% After reaching the top, all further moves must be 0
% That is, once a 0 appears, all following must be 0
constraint forall(i in 1..n-1) (
    (steps[i] = 0) -> (steps[i+1] = 0)
);

% Optional: minimize the number of moves (non-zero steps)
% This is not required, but can be uncommented if you want the shortest sequence
% var int: num_moves = sum(i in Moves)(bool2int(steps[i] > 0));
% solve minimize num_moves;

solve satisfy;

output [
    "{",
    "\"steps\": [", join(",", [show(steps[i]) | i in Moves]), "]",
    "}"
];
```

