include "globals.mzn";

% Input data
% Countries: 1=Belgium, 2=Denmark, 3=France, 4=Germany, 5=Netherlands, 6=Luxembourg
int: n_countries = 6;
set of int: Countries = 1..n_countries;

% Adjacency list as pairs (i, j) where i < j
array[1..9, 1..2] of int: graph = 
    [| 3, 1 |  % France - Belgium
       3, 6 |  % France - Luxembourg
       3, 4 |  % France - Germany
       6, 4 |  % Luxembourg - Germany
       6, 1 |  % Luxembourg - Belgium
       1, 5 |  % Belgium - Netherlands
       1, 4 |  % Belgium - Germany
       4, 5 |  % Germany - Netherlands
       4, 2 |  % Germany - Denmark
    |];

% Decision variables
array[Countries] of var 1..n_countries: colors; % color assigned to each country

% Minimize the number of colors used
var 1..n_countries: num_colors;
constraint num_colors = max(colors);

% Constraints: adjacent countries must have different colors
constraint
    forall(e in 1..9) (
        colors[graph[e,1]] != colors[graph[e,2]]
    );

solve minimize num_colors;

output [
    "{",
    "\"colors\": [" ++ join(",", [show(colors[i]) | i in Countries]) ++ "]",
    "}"
];
```

