% Index sets
int: N = 5;
set of int: IDX = 1..N;

% Children
enum CHILD = {Bernice, Carl, Debby, Sammy, Ted};
array[IDX] of CHILD: children_enum = [Bernice, Carl, Debby, Sammy, Ted];

% Countries
enum COUNTRY = {Ethiopia, Kazakhstan, Lithuania, Morocco, Yemen};
array[IDX] of COUNTRY: countries_enum = [Ethiopia, Kazakhstan, Lithuania, Morocco, Yemen];

% Stories
enum STORY = {BurningBush, Captivity, MosesYouth, Passover, TenCommandments};
array[IDX] of STORY: stories_enum = [BurningBush, Captivity, MosesYouth, Passover, TenCommandments];

% Ages
array[IDX] of int: ages_domain = [3, 5, 7, 8, 10];

% Decision variables: permutation of 1..5 for each category
array[IDX] of var 1..N: ages;      % ages[i] = position in ages_domain for child i
array[IDX] of var 1..N: children;  % children[i] = child at position i
array[IDX] of var 1..N: countries; % countries[i] = country at position i
array[IDX] of var 1..N: stories;   % stories[i] = story at position i

% All are permutations
constraint all_different(ages);
constraint all_different(children);
constraint all_different(countries);
constraint all_different(stories);

% Helper: For each child, get their index
function int: child_idx(CHILD c) = index_set(children_enum)[children_enum = c][1];
function int: country_idx(COUNTRY c) = index_set(countries_enum)[countries_enum = c][1];
function int: story_idx(STORY s) = index_set(stories_enum)[stories_enum = s][1];

% 1. Debby’s family is from Lithuania.
constraint
    let {
        var 1..N: debby_pos = index_set(children)[children = child_idx(Debby)][1],
        var 1..N: lithuania_pos = index_set(countries)[countries = country_idx(Lithuania)][1]
    } in
        debby_pos = lithuania_pos;

% 2. The child who told the story of the Passover is two years older than Bernice.
constraint
    let {
        var 1..N: passover_pos = index_set(stories)[stories = story_idx(Passover)][1],
        var 1..N: bernice_pos = index_set(children)[children = child_idx(Bernice)][1]
    } in
        ages[passover_pos] = ages[bernice_pos] + 2;

% 3. The child whose family is from Yemen is younger than the child from the Ethiopian family.
constraint
    let {
        var 1..N: yemen_pos = index_set(countries)[countries = country_idx(Yemen)][1],
        var 1..N: ethiopia_pos = index_set(countries)[countries = country_idx(Ethiopia)][1]
    } in
        ages[yemen_pos] < ages[ethiopia_pos];

% 4. The child from the Moroccan family is three years older than Ted.
constraint
    let {
        var 1..N: morocco_pos = index_set(countries)[countries = country_idx(Morocco)][1],
        var 1..N: ted_pos = index_set(children)[children = child_idx(Ted)][1]
    } in
        ages[morocco_pos] = ages[ted_pos] + 3;

% 5. Sammy is three years older than the child who told the story of Moses’s youth in the house of the Pharaoh.
constraint
    let {
        var 1..N: sammy_pos = index_set(children)[children = child_idx(Sammy)][1],
        var 1..N: mosesyouth_pos = index_set(stories)[stories = story_idx(MosesYouth)][1]
    } in
        ages[sammy_pos] = ages[mosesyouth_pos] + 3;

% Ages must be from the domain
constraint forall(i in IDX)(ages[i] = ages_domain[i]);

solve satisfy;

output [
    "{",
    "\"ages\": [" ++ join(",", [show(ages[i]) | i in IDX]) ++ "],",
    "\"children\": [" ++ join(",", [show(children[i]) | i in IDX]) ++ "],",
