include "globals.mzn";

% Number of cows and sons
int: num_cows = 25;
int: num_sons = 5;

% Number of cows per son (in order: son 0 gets 7, son 1 gets 6, ..., son 4 gets 3)
array[0..4] of int: cows_per_son = [7, 6, 5, 4, 3];

% Milk produced by each cow (cow i gives i+1 kg)
array[1..num_cows] of int: milk = [i | i in 1..num_cows];

% Decision variable: cow_assignments[i] = s means cow i is assigned to son s (0..4)
array[1..num_cows] of var 0..4: cow_assignments;

% For each son, the set of cows assigned to him
array[0..4] of var set of 1..num_cows: cows_of_son;

% For each son, the total milk he gets
array[0..4] of var int: milk_of_son;

% Constraints

% Each cow assigned to exactly one son
% (already enforced by the domain of cow_assignments)

% Each son gets the required number of cows
constraint
    forall(s in 0..4) (
        count(cow_assignments, s) = cows_per_son[s+1]
    );

% Build the set of cows for each son
constraint
    forall(s in 0..4) (
        cows_of_son[s] = {i | i in 1..num_cows where cow_assignments[i] = s}
    );

% Each son gets the same total milk
constraint
    forall(s in 0..4) (
        milk_of_son[s] = sum([milk[i] | i in 1..num_cows where cow_assignments[i] = s])
    );

constraint
    forall(s in 1..4) (
        milk_of_son[s] = milk_of_son[0]
    );

solve satisfy;

output [
    "{",
    "\"cow_assignments\": [", join(",", [show(cow_assignments[i]) | i in 1..num_cows]), "]",
    "}"
];
```

