```minizinc
% The 7.11 problem: Find four item prices in cents such that their sum and product are both 711.

include "globals.mzn";

int: total = 711; % total in cents

% Decision variables: prices of the four items in cents
array[1..4] of var 1..total: prices;

% Constraints
constraint sum(prices) == total;
constraint prices[1] * prices[2] * prices[3] * prices[4] == total * 100 * 100 * 100; 
% Since all prices are in cents, and the product must be $7.11, i.e., 7.11 dollars = 711 cents,
% but the product of four prices in cents must be 7.11 dollars, so 7.11 = x1 * x2 * x3 * x4 (in dollars)
% So, in cents: (x1/100)*(x2/100)*(x3/100)*(x4/100) = 7.11
% => (x1*x2*x3*x4) = 7.11 * 100^4 = 711000000
% But 100^4 = 100000000, so 7.11 * 100000000 = 711000000
% So, the product in cents must be 711000000

constraint forall(i in 1..4)(prices[i] <= total - 3); % Each price must be at most 708 cents

% To avoid symmetric solutions, enforce non-decreasing order
constraint prices[1] <= prices[2];
constraint prices[2] <= prices[3];
constraint prices[3] <= prices[4];

solve satisfy;

output [
    "{",
    "\"prices\": [" ++ join(",", [show(prices[i]) | i in 1..4]) ++ "]",
    "}"
];
```

