% Include the global constraints library
include "globals.mzn";

% Input data
int: n = 8;
array[1..n] of set of int: adjacency_list = [
    {2, 3, 7},
    {1, 4, 8},
    {1, 4, 5},
    {2, 3, 6},
    {3, 6, 7},
    {4, 5, 8},
    {1, 5, 8},
    {2, 6, 7}
];

% Decision variables: nodes[i] = 1 if node i is in the independent set, 0 otherwise
array[1..n] of var 0..1: nodes;

% Constraint 1: No two adjacent nodes are both in the independent set
constraint
    forall(i in 1..n, j in adjacency_list[i]) (
        i < j -> nodes[i] + nodes[j] <= 1
    );

% Constraint 2: Maximality - for every node not in the set, at least one neighbor is in the set
constraint
    forall(i in 1..n) (
        nodes[i] = 1 \/
        exists(j in adjacency_list[i]) (
            nodes[j] = 1
        )
    );

solve satisfy;

output [
    "{",
    "\"nodes\": [" ++ join(",", [show(nodes[i]) | i in 1..n]) ++ "]",
    "}"
];
