% Include necessary library
include "globals.mzn";

% Problem data
int: n_people = 13;
int: n_males = 4;
int: n_females = 9;

% Decision variables
% sequence[i] = 0 if the i-th person to enter is male, 1 if female
array[1..n_people] of var 0..1: sequence;

% There must be exactly n_males males and n_females females in the sequence
constraint sum([sequence[i] | i in 1..n_people]) = n_females;
constraint sum([1-sequence[i] | i in 1..n_people]) = n_males;

% At any time, the ratio of females to males in the room is <= 7/3
% For each prefix 1..k, females_so_far / males_so_far <= 7/3
% To avoid division by zero, only check when at least one male is present
constraint forall(k in 1..n_people) (
    let {
        var int: females_so_far = sum([sequence[i] | i in 1..k]),
        var int: males_so_far = k - females_so_far
    } in
        (males_so_far = 0 \/ 3*females_so_far <= 7*males_so_far)
);

solve satisfy;

output [
    "{",
    "\"sequence\": [" ++ join(",", [show(sequence[i]) | i in 1..n_people]) ++ "]",
    "}"
];
```

