% Include the standard globals library
include "globals.mzn";

% There are 6 suspects: Artie, Bill, Crackitt, Dodgy, Edgy, Fingers
% 1 = guilty, 0 = innocent
array[1..6] of var 0..1: guilty;
% For readability, assign names to indices
int: ARTIE = 1;
int: BILL = 2;
int: CRACKITT = 3;
int: DODGY = 4;
int: EDGY = 5;
int: FINGERS = 6;

% At least 4 are innocent (so at most 2 are guilty, since the car fits 2)
constraint sum(guilty) <= 2;
constraint sum(guilty) >= 1; % At least one guilty

% Innocent tell the truth, guilty lie

% ARTIE: "It wasn't me."
% If innocent, this is true: guilty[ARTIE] = 0
% If guilty, this is false: guilty[ARTIE] = 1
% So, for both cases, the statement "guilty[ARTIE] = 0" is true iff innocent
constraint (guilty[ARTIE] = 0) <-> (guilty[ARTIE] = 0);

% BILL: "Crackitt was in it up to his neck."
% If innocent, this is true: guilty[CRACKITT] = 1
% If guilty, this is false: guilty[CRACKITT] = 0
constraint (guilty[BILL] = 0) <-> (guilty[CRACKITT] = 1);

% CRACKITT: "No I wasn't."
% If innocent, this is true: guilty[CRACKITT] = 0
% If guilty, this is false: guilty[CRACKITT] = 1
constraint (guilty[CRACKITT] = 0) <-> (guilty[CRACKITT] = 0);

% DODGY: "If Crackitt did it, Bill did it with him."
% If innocent, this is true: guilty[CRACKITT]=1 -> guilty[BILL]=1
% If guilty, this is false: guilty[CRACKITT]=1 /\ guilty[BILL]=0
constraint (guilty[DODGY] = 0) <-> (guilty[CRACKITT]=0 \/ guilty[BILL]=1);

% EDGY: "Nobody did it alone."
% If innocent, this is true: sum(guilty) != 1
% If guilty, this is false: sum(guilty) = 1
constraint (guilty[EDGY] = 0) <-> (sum(guilty) != 1);

% FINGERS: "That's right: it was Artie and Dodgy together."
% If innocent, this is true: guilty[ARTIE]=1 /\ guilty[DODGY]=1 /\ sum(guilty)=2
% If guilty, this is false: not (guilty[ARTIE]=1 /\ guilty[DODGY]=1 /\ sum(guilty)=2)
constraint (guilty[FINGERS] = 0) <-> (guilty[ARTIE]=1 /\ guilty[DODGY]=1 /\ sum(guilty)=2);

solve satisfy;

output [
    "{",
    "\"artie\": ", show(guilty[ARTIE]), ", ",
    "\"bill\": ", show(guilty[BILL]), ", ",
    "\"crackitt\": ", show(guilty[CRACKITT]), ", ",
    "\"dodgy\": ", show(guilty[DODGY]), ", ",
    "\"edgy\": ", show(guilty[EDGY]), ", ",
    "\"fingers\": ", show(guilty[FINGERS]),
    "}"
];
