% Each bus can operate only 8 successive hours (i.e., 2 slots)
% Decision variable: x[i] = number of buses starting at slot i (and thus covering slot i and i+1)
array[1..n_slots] of var 0..100: x;

% For each slot, the buses available are those that started in this slot or the previous slot
% (since each bus covers 2 slots: its start slot and the next one, with wrap-around)
constraint
  forall(i in 1..n_slots) (
    let {
      int: prev = if i = 1 then n_slots else i-1
    } in
      x[i] + x[prev] >= demands[i]
  );

% Objective: minimize total number of buses scheduled
solve minimize sum(x);

output [
    "{",
    "\"x\": [" ++ join(",", [show(x[i]) | i in 1..n_slots]) ++ "]",
    "}"
];
