% Input data
% jobs_data: array of jobs, each job is a list of (machine_id, duration)
% jobs_data = [
%   [(0, 3), (1, 2), (2, 2)],  % Job 0
%   [(0, 2), (2, 1), (1, 4)],  % Job 1
%   [(1, 4), (2, 3)]           % Job 2
% ]

int: num_jobs = 3;
array[1..num_jobs] of int: num_tasks = [3, 3, 2];

% Flattened machine and duration data for each task in each job
array[1..num_jobs, 1..max(num_tasks)] of int: machine = 
  array2d(1..num_jobs, 1..max(num_tasks), [
    0, 1, 2,   % Job 0
    0, 2, 1,   % Job 1
    1, 2, 0    % Job 2 (pad with 0 for missing task)
  ]);
array[1..num_jobs, 1..max(num_tasks)] of int: duration = 
  array2d(1..num_jobs, 1..max(num_tasks), [
    3, 2, 2,   % Job 0
    2, 1, 4,   % Job 1
    4, 3, 0    % Job 2 (pad with 0 for missing task)
  ]);

% Find the number of machines
int: num_machines = 1 + max([machine[j, t] | j in 1..num_jobs, t in 1..num_tasks[j]]);

% Decision variables: start time for each task
array[1..num_jobs, 1..max(num_tasks)] of var 0..100: start;

% Only define variables for real tasks (not padded zeros)
function bool: is_real_task(int: j, int: t) = t <= num_tasks[j];

% Precedence constraints: tasks in a job must be sequential
constraint
  forall(j in 1..num_jobs, t in 1..num_tasks[j]-1) (
    start[j, t+1] >= start[j, t] + duration[j, t]
  );

% Machine constraints: no overlap on the same machine
constraint
  forall(m in 0..num_machines-1) (
    let {
      set of int: jobset = {j | j in 1..num_jobs, t in 1..num_tasks[j], machine[j, t] == m},
      set of int: taskset = {t | j in 1..num_jobs, t in 1..num_tasks[j], machine[j, t] == m},
      set of tuple(int, int): tasks_on_m = {(j, t) | j in 1..num_jobs, t in 1..num_tasks[j], machine[j, t] == m}
    } in
      forall((j1, t1) in tasks_on_m, (j2, t2) in tasks_on_m where (j1, t1) < (j2, t2)) (
        (start[j1, t1] + duration[j1, t1] <= start[j2, t2]) \/
        (start[j2, t2] + duration[j2, t2] <= start[j1, t1])
      )
  );

% Each task must start after 0 and finish before makespan
var 0..100: makespan;

constraint
  forall(j in 1..num_jobs, t in 1..num_tasks[j]) (
    start[j, t] + duration[j, t] <= makespan
  );

% Tasks with duration 0 (padded) must start at 0
constraint
  forall(j in 1..num_jobs, t in num_tasks[j]+1..max(num_tasks)) (
    start[j, t] = 0 /\ duration[j, t] = 0
  );

solve minimize makespan;

output [
  "{",
  "\"makespan\": ", show(makespan),
  "}"
];
