% Include the global constraints library
include "globals.mzn";

% Input data
int: X = -1;
array[1..8, 1..8] of int: game_data = 
[
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
];

int: N = 8;

% Decision variables: mines[i,j] = 1 if there is a mine at (i,j), 0 otherwise
array[1..N, 1..N] of var 0..1: mines;

% Helper: directions for 8 neighbors
set of int: D = {-1, 0, 1};

% Constraints
constraint
    forall(i in 1..N, j in 1..N where game_data[i,j] != X) (
        let {
            set of int: ni = {ii | ii in i-1..i+1 where ii >= 1 /\ ii <= N},
            set of int: nj = {jj | jj in j-1..j+1 where jj >= 1 /\ jj <= N},
            array[int] of var 0..1: neighbors = 
                [mines[ii,jj] | ii in ni, jj in nj where not (ii == i /\ jj == j)]
        } in
            sum(neighbors) == game_data[i,j]
    )
    /\
    forall(i in 1..N, j in 1..N where game_data[i,j] != X) (
        % Opened cells cannot be mines
        mines[i,j] = 0
    );

% Unopened cells (X) can be mines or not, so no further constraint needed

solve satisfy;

output [
    "{\n\"mines\": [\n",
    join(",\n", [
        "  [" ++ join(",", [show(mines[i,j]) | j in 1..N]) ++ "]"
        | i in 1..N
    ]),
    "]\n}"
];
