include "globals.mzn";

% Input data
int: N = 20; % Number of steps
int: R = 3;  % Number of rows
int: C = 3;  % Number of columns
int: NUM_TILES = R * C;

array[1..R, 1..C] of int: puzzle_start = 
    array2d(1..R, 1..C, [0, 3, 6,
                         2, 4, 8,
                         1, 7, 5]);

array[1..R, 1..C] of int: puzzle_end = 
    array2d(1..R, 1..C, [1, 2, 3,
                         4, 5, 6,
                         7, 8, 0]);

set of int: TILES = 0..(NUM_TILES-1);

% Decision variables: steps[s, r, c] is the tile at (r,c) at step s
array[0..N, 1..R, 1..C] of var TILES: steps;

% Each step must be a permutation of the tiles (all tiles present, no duplicates)
constraint forall(s in 0..N) (
    all_different([steps[s, r, c] | r in 1..R, c in 1..C])
);

% Initial and final state constraints
constraint forall(r in 1..R, c in 1..C) (
    steps[0, r, c] = puzzle_start[r, c] /\
