% Helper: convert date string "YYYY-MM-DD" to integer (days since 2024-05-01)
function int: date_to_int(string: d) =
    let {
        int: y = str_to_int(substring(d,1,4)),
        int: m = str_to_int(substring(d,6,7)),
        int: day = str_to_int(substring(d,9,10))
    } in
    (y - 2024) * 365 + (m - 5) * 31 + (day - 1);

array[1..n] of int: start = [date_to_int(s) | s in start_data];
array[1..n] of int: end_  = [date_to_int(e) | e in end_data];

% Decision variables: room assigned to each request (1..max_rooms)
array[1..n] of var 1..max_rooms: room_assignments;

% Apply pre-assignments
constraint
    forall(i in 1..n where preassigned_room_data[i] != -1) (
        room_assignments[i] = preassigned_room_data[i]
    );

% No overlapping requests in the same room
constraint
    forall(i, j in 1..n where i < j) (
        (room_assignments[i] != room_assignments[j]) \/
        (end_[i] < start[j]) \/
        (end_[j] < start[i])
    );

solve satisfy;

output [
    "{",
    "\"room_assignments\": [", join(",", [show(room_assignments[i]) | i in 1..n]), "]",
    "}"
];
