include "globals.mzn";

% Input data
int: n = 12;
array[1..n] of int: x = [288, 288, 270, 256, 256, 246, 236, 228, 228, 220, 212, 204];
array[1..n] of int: y = [149, 129, 133, 141, 163, 157, 169, 169, 148, 164, 172, 159];

% Precompute the distance matrix (Euclidean, rounded to nearest integer)
array[1..n, 1..n] of int: dist = 
  array2d(1..n, 1..n, [
    round(sqrt((x[i]-x[j])^2 + (y[i]-y[j])^2)) | i in 1..n, j in 1..n
  ]);

% Decision variables
array[1..n] of var 1..n: succ; % succ[i] is the city visited after city i

% Each city must be visited exactly once, and form a circuit
constraint circuit(succ);

% Compute the total travel distance
var int: travel_distance = sum(i in 1..n)(dist[i, succ[i]]);

solve minimize travel_distance;

output [
    "{",
    "\"travel_distance\": ", show(travel_distance),
    "}"
];
