constraint goat_pos[stage] = 1;
constraint cabbage_pos[stage] = 1;
constraint boat_pos[stage] = 1;

% At each stage, only the farmer (boat) moves, possibly with one item
% For each step, only the boat and at most one of wolf, goat, cabbage can change position
constraint
