    let {
      % Who moves with the boat? (0=alone, 1=wolf, 2=goat, 3=cabbage)
      var 0..3: move,
      % The boat must move
      var 0..1: new_side = 1 - boat_pos[t]
    } in
      % Only one of wolf, goat, cabbage can move with the boat, or none
      (
        (move = 0 /\ wolf_pos[t+1] = wolf_pos[t] /\ goat_pos[t+1] = goat_pos[t] /\ cabbage_pos[t+1] = cabbage_pos[t]) \/
        (move = 1 /\ wolf_pos[t+1] = new_side /\ goat_pos[t+1] = goat_pos[t] /\ cabbage_pos[t+1] = cabbage_pos[t] /\ wolf_pos[t] = boat_pos[t]) \/
        (move = 2 /\ goat_pos[t+1] = new_side /\ wolf_pos[t+1] = wolf_pos[t] /\ cabbage_pos[t+1] = cabbage_pos[t] /\ goat_pos[t] = boat_pos[t]) \/
        (move = 3 /\ cabbage_pos[t+1] = new_side /\ wolf_pos[t+1] = wolf_pos[t] /\ goat_pos[t+1] = goat_pos[t] /\ cabbage_pos[t] = boat_pos[t])
      )
      /\
      % The boat always moves
      boat_pos[t+1] = new_side
  );

% At no stage can the goat and cabbage be left alone together without the farmer
constraint
  forall(t in 1..stage) (
    (goat_pos[t] = cabbage_pos[t] /\ goat_pos[t] != boat_pos[t]) -> (goat_pos[t] != wolf_pos[t])
