```minizinc
include "globals.mzn";

% Input data
int: n_slots = 9; % Number of slots on a template
int: n_templates = 2; % Number of templates
int: n_var = 7; % Number of different variations
array[1..n_var] of int: demand = [250, 255, 260, 500, 500, 800, 1100];

% Decision variables

% layout[t, s]: which variation is assigned to slot s of template t (0 means empty slot)
array[1..n_templates, 1..n_slots] of var 0..n_var: layout;

% For each template, how many sheets are printed
array[1..n_templates] of var 0..sum(demand): sheets;

% For each template, for each variation, how many times does that variation appear on the template
array[1..n_templates, 1..n_var] of var 0..n_slots: var_on_template;

% For each variation, total produced
array[1..n_var] of var 0..sum(demand): produced;

% Constraints

% For each template and variation, count how many times the variation appears on the template
constraint
  forall(t in 1..n_templates, v in 1..n_var) (
    var_on_template[t, v] = count([layout[t, s] | s in 1..n_slots], v)
  );

% No empty templates: at least one slot is used in each template
constraint
  forall(t in 1..n_templates) (
    sum([bool2int(layout[t, s] > 0) | s in 1..n_slots]) > 0
  );

% For each slot, either empty or assigned to a variation
% (already enforced by domain 0..n_var)

% For each variation, total produced must meet or exceed demand
constraint
  forall(v in 1..n_var) (
    produced[v] = sum([sheets[t] * var_on_template[t, v] | t in 1..n_templates]) /\
    produced[v] >= demand[v]
  );

% For each template, the number of slots used is at most n_slots
constraint
  forall(t in 1..n_templates) (
    sum([bool2int(layout[t, s] > 0) | s in 1..n_slots]) <= n_slots
  );

% For each template, if a slot is empty, it is 0
% (already enforced by domain)

% For each template, if a template is not used (sheets[t] = 0), all slots must be empty
constraint
  forall(t in 1..n_templates) (
    (sheets[t] = 0) -> forall(s in 1..n_slots) (layout[t, s] = 0)
  );

% For each template, if a slot is used, the template must be used (sheets[t] > 0)
constraint
  forall(t in 1..n_templates, s in 1..n_slots) (
    (layout[t, s] > 0) -> (sheets[t] > 0)
  );

% Try to minimize the total number of sheets printed
var int: production = sum(sheets);

solve minimize production;

output [
    "{",
    "\"production\": ", show(production), ", ",
    "\"layout\": [",
    join(",", [
        "[" ++ join(",", [show(layout[t, s]) | s in 1..n_slots]) ++ "]"
        | t in 1..n_templates
    ]),
    "]",
    "}"
];
```

