% Low Autocorrelation Binary Sequences (LABS) Problem
% n = 10, periodic (cyclic) boundary conditions

int: n = 10;

% Decision variables: sequence of +1/-1
array[0..n-1] of var {-1,1}: sequence;

% Autocorrelation values for k = 1..n-1
array[1..n-1] of var -n..n: C;

% Compute C_k = sum_{i=0}^{n-1} S_i * S_{(i+k) mod n}
constraint
  forall(k in 1..n-1) (
    C[k] = sum(i in 0..n-1) (sequence[i] * sequence[(i + k) mod n])
  );

% Energy: sum of squares of autocorrelations
var 0..n*n*(n-1): E;
constraint
  E = sum(k in 1..n-1)(C[k]*C[k]);

solve minimize E;

output [
    "{",
    "\"sequence\": [" ++ join(",", [show(sequence[i]) | i in 0..n-1]) ++ "],",
    "\"E\": " ++ show(E),
    "}"
];
```

