% Input data
int: size = 10; % Number of marks on the Golomb ruler

% Decision variables
array[1..size] of var 0..1000: marks; % Positions of the marks (upper bound is arbitrary, can be increased if needed)
var 0..1000: length = marks[size];    % Length of the ruler is the last mark

% The marks are strictly increasing, and the first mark is at 0
constraint marks[1] = 0;
constraint forall(i in 1..size-1) (
    marks[i] < marks[i+1]
);

% All pairwise differences must be distinct
% There are size*(size-1)/2 differences
int: num_diffs = size * (size - 1) div 2;
array[1..num_diffs] of var 1..1000: diffs;

% Fill the diffs array with all differences marks[j] - marks[i] for 1 <= i < j <= size
% We'll use a mapping from (i,j) to k in 1..num_diffs
% Let's build the mapping
array[1..num_diffs] of int: diff_i = [i | i in 1..size-1, j in i+1..size];
array[1..num_diffs] of int: diff_j = [j | i in 1..size-1, j in i+1..size];

constraint
    forall(k in 1..num_diffs) (
        diffs[k] = marks[diff_j[k]] - marks[diff_i[k]]
    );

% All differences must be distinct
constraint all_different(diffs);

% Symmetry breaking: first difference is less than the last
constraint (marks[2] - marks[1]) < (marks[size] - marks[size-1]);

% Objective: minimize the length of the ruler
solve minimize length;

output [
    "{",
    "\"marks\": [" ++ join(",", [show(marks[i]) | i in 1..size]) ++ "],",
    "\"length\": " ++ show(length),
    "}"
];
