% Input data
int: n = 12; % Number of pitch-classes

% Decision variables
array[1..n] of var 0..n-1: x;         % The sequence of pitch-classes
array[1..n-1] of var 1..n-1: diffs;   % The sequence of intervals (absolute differences)

% Constraints

% 1. x is a permutation of 0..n-1
constraint all_different(x);

% 2. diffs[i] = |x[i+1] - x[i]| for i in 1..n-1, modulo n
constraint
    forall(i in 1..n-1) (
        diffs[i] = let {
            var int: d = x[i+1] - x[i]
        } in
            min(abs(d), n - abs(d))
    );

% 3. diffs is a permutation of 1..n-1
constraint all_different(diffs);

% Optional: symmetry breaking (fix first pitch-class and order of first interval)
constraint x[1] = 0;
constraint diffs[1] < diffs[n-1];

solve satisfy;

output [
    "{",
    "\"x\": [" ++ join(",", [show(x[i]) | i in 1..n]) ++ "],",
    "\"diffs\": [" ++ join(",", [show(diffs[i]) | i in 1..n-1]) ++ "]",
    "}"
];
