% Include global constraints
include "globals.mzn";

% ----------------------
% Input data
% ----------------------
int: deck_width = 5;
int: deck_length = 5;
int: n_containers = 3;
array[1..n_containers] of int: width = [5, 2, 3];
array[1..n_containers] of int: length = [1, 4, 4];
array[1..n_containers] of int: classes = [1, 1, 1];
int: n_classes = 1; % Only class 1 is used
array[1..n_classes, 1..n_classes] of int: separation = 
    array2d(1..n_classes, 1..n_classes, [0, 0]);

% ----------------------
% Decision variables
% ----------------------
% The (x, y) position of the bottom-left corner of each container
array[1..n_containers] of var 0..deck_width: left;
array[1..n_containers] of var 0..deck_length: bottom;

% The (x, y) position of the top-right corner of each container
array[1..n_containers] of var 0..deck_width: right;
array[1..n_containers] of var 0..deck_length: top;

% ----------------------
% Constraints
% ----------------------

% 1. Each container must be within the deck
constraint forall(i in 1..n_containers) (
    left[i] >= 0 /\
    bottom[i] >= 0 /\
    right[i] = left[i] + width[i] /\
    top[i] = bottom[i] + length[i] /\
    right[i] <= deck_width /\
    top[i] <= deck_length
);

% 2. No overlapping between containers
constraint forall(i, j in 1..n_containers where i < j) (
    right[i] <= left[j] \/
    right[j] <= left[i] \/
    top[i] <= bottom[j] \/
    top[j] <= bottom[i]
);

% 3. Separation constraints between classes (not needed here, but for completeness)
constraint forall(i, j in 1..n_containers where i < j) (
    let {
        int: ci = classes[i],
        int: cj = classes[j]
    } in
    (separation[ci, cj] = 0 \/ (
        right[i] + separation[ci, cj] <= left[j] \/
        right[j] + separation[ci, cj] <= left[i] \/
        top[i] + separation[ci, cj] <= bottom[j] \/
        top[j] + separation[ci, cj] <= bottom[i]
    ))
);

% 4. Loading sequence constraints:
% Each container (except the first) must touch a wall or another container to the north and to the west.
% The southeast corner is (0,0). "Touch north" means top[i] = deck_length or top[i] = bottom[j] for some j != i.
% "Touch west" means left[i] = 0 or right[j] = left[i] for some j != i.
constraint forall(i in 2..n_containers) (
    % Touch north: either top[i] = deck_length (touches north wall) or top[i] = bottom[j] for some j != i and overlap in x
    (
        top[i] = deck_length \/
        exists(j in 1..n_containers where j != i) (
            top[i] = bottom[j] /\
            % Overlap in x
            not (right[i] <= left[j] \/ right[j] <= left[i])
        )
    )
    /\
    % Touch west: either left[i] = 0 (touches west wall) or right[j] = left[i] for some j != i and overlap in y
    (
        left[i] = 0 \/
        exists(j in 1..n_containers where j != i) (
            right[j] = left[i] /\
            not (top[i] <= bottom[j] \/ top[j] <= bottom[i])
        )
    )
);

% The first container must be in the southeast corner (touches both south and east walls)
constraint bottom[1] = 0 /\ left[1] = 0;

% ----------------------
% Output
% ----------------------
output [
    "{",
    "\"left\": [", join(",", [show(left[i]) | i in 1..n_containers]), "],",
    "\"right\": [", join(",", [show(right[i]) | i in 1..n_containers]), "],",
    "\"top\": [", join(",", [show(top[i]) | i in 1..n_containers]), "],",
    "\"bottom\": [", join(",", [show(bottom[i]) | i in 1..n_containers]), "]",
    "}"
];

solve satisfy;
