```minizinc
include "globals.mzn";

% Input data
int: n_weeks = 4;
int: n_groups = 3;
int: group_size = 3;

int: n_golfers = n_groups * group_size;

set of int: WEEKS = 1..n_weeks;
set of int: GROUPS = 1..n_groups;
set of int: SLOTS = 1..group_size;
set of int: GOLFERS = 1..n_golfers;

% Decision variables:
% assign[w,g,s] = golfer assigned to week w, group g, slot s
array[WEEKS, GROUPS, SLOTS] of var GOLFERS: assign;

% Each golfer plays exactly once per week
constraint
  forall(w in WEEKS) (
    all_different([assign[w,g,s] | g in GROUPS, s in SLOTS])
  );

% Each group in each week has different golfers
constraint
  forall(w in WEEKS, g in GROUPS) (
    all_different([assign[w,g,s] | s in SLOTS])
  );

% No pair of golfers plays together in a group more than once
constraint
  forall(g1 in GOLFERS, g2 in GOLFERS where g1 < g2) (
    sum([
      exists(g in GROUPS)(
        exists(s1 in SLOTS, s2 in SLOTS where s1 != s2)(
          (assign[w,g,s1] == g1 /\ assign[w,g,s2] == g2)
        )
      )
      | w in WEEKS
    ]) <= 1
  );

solve satisfy;

output [
  "{",
  "\"assign\": [",
    join(",", [
      "[" ++
        join(",", [
          "[" ++ join(",", [show(assign[w,g,s]) | s in SLOTS]) ++ "]"
          | g in GROUPS
        ]) ++ "]"
      | w in WEEKS
    ]),
  "]",
  "}"
];
```

