include "globals.mzn";

% Input data
int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

set of int: BOATS = 1..n_boats;
set of int: PERIODS = 1..n_periods;

% Decision variables
array[BOATS] of var bool: is_host; % is_host[b] = true if boat b is a host

% visits[g, h, t] = 1 if guest boat g visits host h at period t
array[BOATS, BOATS, PERIODS] of var bool: visits;

% 1. A boat cannot visit itself
constraint forall(g in BOATS, h in BOATS, t in PERIODS) (
    g == h -> visits[g, h, t] = false
);

% 2. Only host boats can be visited
constraint forall(g in BOATS, h in BOATS, t in PERIODS) (
    visits[g, h, t] -> is_host[h]
);

% 3. Host boats do not visit anyone (they stay on their own boat)
constraint forall(h in BOATS, t in PERIODS) (
    is_host[h] -> forall(h2 in BOATS where h2 != h) (
        visits[h, h2, t] = false
    )
);

% 4. Each guest boat visits at most one host per period
constraint forall(g in BOATS, t in PERIODS) (
    sum([visits[g, h, t] | h in BOATS]) <= 1
);

% 5. Host boats do not visit anyone (they stay on their own boat)
constraint forall(h in BOATS, t in PERIODS) (
    is_host[h] -> sum([visits[h, h2, t] | h2 in BOATS]) = 0
);

% 6. A guest boat cannot visit the same host more than once
constraint forall(g in BOATS, h in BOATS) (
    sum([visits[g, h, t] | t in PERIODS]) <= 1
);

% 7. Guest crews cannot meet more than once
% For each pair of guest boats (g1, g2), they cannot be together on the same host in more than one period
constraint forall(g1 in BOATS, g2 in BOATS where g1 < g2) (
    sum([visits[g1, h, t] /\ visits[g2, h, t] | h in BOATS, t in PERIODS]) <= 1
);

% 8. Capacity constraints: For each host h and period t, the sum of all crews on board <= capacity
constraint forall(h in BOATS, t in PERIODS) (
    sum([crew_size[g] * visits[g, h, t] | g in BOATS where g != h]) + crew_size[h] <= capacity[h]
);

% 9. Guest boats must visit a host in every period (cannot stay on their own boat)
constraint forall(g in BOATS, t in PERIODS) (
    not is_host[g] -> sum([visits[g, h, t] | h in BOATS]) = 1
);

% 10. Host boats do not visit anyone
constraint forall(h in BOATS, t in PERIODS) (
    is_host[h] -> sum([visits[h, h2, t] | h2 in BOATS]) = 0
);

% 11. Guest boats do not host (i.e., if not a host, they are always a guest)
constraint forall(g in BOATS, t in PERIODS) (
    not is_host[g] -> visits[g, g, t] = false
);

% Objective: Minimize the number of host boats
solve minimize sum([bool2int(is_host[b]) | b in BOATS]);

% Output: visits[g, h, t] and is_host
output [
    "{",
    "\"visits\": [",
    join(",", [
        "[" ++
        join(",", [
            "[" ++
            join(",", [show(bool2int(visits[g, h, t])) | t in PERIODS]) ++
            "]"
            | h in BOATS
        ]) ++
        "]"
        | g in BOATS
    ]),
    "], ",
    "\"is_host\": [" ++ join(",", [show(bool2int(is_host[b])) | b in BOATS]) ++ "]",
    "}"
];
```

