% Magic Sequence of length n
% A magic sequence x[0..n-1] is such that for all i in 0..n-1, x[i] in 0..n-1,
% and for all i, the number i occurs exactly x[i] times in the sequence.

int: n = 12;

array[0..n-1] of var 0..n-1: x;

% For each i in 0..n-1, the number i occurs exactly x[i] times in x
constraint
    forall(i in 0..n-1) (
        count(x, i) == x[i]
    );

solve satisfy;

output [
    "{",
    "\"x\": [" ++ join(",", [show(x[i]) | i in 0..n-1]) ++ "]",
    "}"
];
