include "globals.mzn";

% Input data
int: k = 4; % Number of sets
int: n = 4; % Numbers from 1 to n

int: total = k * n;

% Each number m appears k times, and the two appearances of m are m numbers apart
% For k=2, this is the classic Langford's problem

% Decision variables:
% position[i]: the position (1..total) of the i-th occurrence of number m
% We'll flatten the positions as: for m in 1..n, for j in 1..k: position[(m-1)*k + j]
array[1..total] of var 1..total: position;

% solution[i]: the number at position i in the sequence
array[1..total] of var 1..n: solution;

% For each number m, its k occurrences must be m numbers apart
% For k=2, for each m, there are two positions: p and p+m+1
% For k>2, the positions are p, p+m+1, p+2*(m+1), ..., etc.

% We'll use a channeling constraint: solution[position[i]] = m for each occurrence

% Build the list of all occurrences: (m, j) for m in 1..n, j in 1..k
array[1..total] of int: num = [m | m in 1..n, j in 1..k];

% Channeling: solution[position[i]] = num[i]
constraint
    forall(i in 1..total) (
        solution[position[i]] = num[i]
    );

% All positions must be different
constraint
    all_different(position);

% For each number m, its k occurrences must be m numbers apart
constraint
    forall(m in 1..n) (
        let {
            array[1..k] of var 1..total: pos = [position[(m-1)*k + j] | j in 1..k]
        } in
        % Sort the positions for this number
        increasing(pos) /\
        forall(j in 1..k-1) (
            pos[j+1] = pos[j] + m + 1
        )
    );

% Each position in the solution must be filled
constraint
    all_different(solution ++ [total+1]); % dummy to avoid warning

% The solution array is a permutation of k sets of 1..n
constraint
    global_cardinality(solution, [i | i in 1..n], [k | i in 1..n]);

solve satisfy;

output [
    "{",
    "\"position\": [", join(",", [show(position[i]) | i in 1..total]), "],",
    "\"solution\": [", join(",", [show(solution[i]) | i in 1..total]), "]",
    "}"
];
```

