constraint forall(w in WEEKS, p in PERIODS) (
    home[w,p] != away[w,p]
);

% Each team plays once per week (either as home or away)
constraint forall(w in WEEKS, t in TEAMS) (
    count([home[w,p] | p in PERIODS] ++ [away[w,p] | p in PERIODS], t) == 1
);

% Each team plays every other team exactly once
constraint forall(t1 in TEAMS, t2 in TEAMS where t1 < t2) (
    sum([bool2int((home[w,p] == t1 /\ away[w,p] == t2) \/ (home[w,p] == t2 /\ away[w,p] == t1)) | w in WEEKS, p in PERIODS]) == 1
);

% Each team plays at most twice in the same period over the tournament
constraint forall(t in TEAMS, p in PERIODS) (
    count([home[w,p] | w in WEEKS] ++ [away[w,p] | w in WEEKS], t) <= 2
);

% No duplicate matches in the same week
constraint forall(w in WEEKS) (
    all_different([home[w,p] | p in PERIODS] ++ [away[w,p] | p in PERIODS])
);

% Symmetry breaking: order home < away in each match
constraint forall(w in WEEKS, p in PERIODS) (
    home[w,p] < away[w,p]
);

solve satisfy;

output [
    "{",
    "\"home\": [",
    join(",", [ "[" ++ join(",", [show(home[w,p]) | p in PERIODS]) ++ "]" | w in WEEKS ]),
    "],",
    "\"away\": [",
    join(",", [ "[" ++ join(",", [show(away[w,p]) | p in PERIODS]) ++ "]" | w in WEEKS ]),
    "]",
    "}"
];
```

