include "globals.mzn";

% Input data
int: n = 8; % Number of words to find
int: word_len = 8;

% Alphabet: A=1, C=2, G=3, T=4
set of int: ALPHABET = 1..4;

% Mapping for Watson-Crick complement:
% A <-> T, C <-> G
array[ALPHABET] of int: complement = [4, 3, 2, 1];

% Decision variables: words[i, j] is the j-th letter of word i
array[1..n, 1..word_len] of var ALPHABET: words;

% Constraint 1: Each word has exactly 4 symbols from {C,G} (i.e., 2 or 3)
constraint
    forall(i in 1..n) (
        sum([bool2int(words[i, j] = 2 \/ words[i, j] = 3) | j in 1..word_len]) = 4
    );

% Constraint 2: Each pair of distinct words differ in at least 4 positions (Hamming distance >= 4)
constraint
    forall(i, j in 1..n where i < j) (
        sum([bool2int(words[i, k] != words[j, k]) | k in 1..word_len]) >= 4
    );

% Helper: Reverse of a word
function array[int] of var int: reverse(array[int] of var int: w) =
    [w[word_len - k + 1] | k in 1..word_len];

% Helper: Watson-Crick complement of a word
function array[int] of var int: wc_complement(array[int] of var int: w) =
    [complement[w[k]] | k in 1..word_len];

% Constraint 3: For all pairs (x, y), x^R and y^C differ in at least 4 positions
constraint
    forall(i, j in 1..n) (
        let {
            array[1..word_len] of var int: xR = reverse([words[i, k] | k in 1..word_len]),
            array[1..word_len] of var int: yC = wc_complement([words[j, k] | k in 1..word_len])
        } in
            sum([bool2int(xR[k] != yC[k]) | k in 1..word_len]) >= 4
    );

% Solve: just find any solution
solve satisfy;

% Output: print the set of words as a list of lists of integers
output [
    "{",
    "\"words\": [",
    join(",\n", [
        "[" ++ join(",", [show(words[i, j]) | j in 1..word_len]) ++ "]"
        | i in 1..n
    ]),
    "]",
    "}"
];
