% Input data
int: n = 9; % Order of the Steiner Triple System

% Number of triples (blocks)
int: num_triples = n * (n - 1) div 6;

% Each triple is a set of 3 distinct elements from 1..n
array[1..num_triples, 1..3] of var 1..n: sets;

% 1. Each triple contains 3 distinct elements, sorted to break symmetry
constraint
    forall(t in 1..num_triples) (
        sets[t,1] < sets[t,2] /\
        sets[t,2] < sets[t,3]
    );

% 2. Any two triples have at most one element in common
constraint
    forall(t1 in 1..num_triples, t2 in t1+1..num_triples) (
        % Count the number of common elements between sets[t1,*] and sets[t2,*]
        sum([bool2int(sets[t1,i] == sets[t2,j]) | i in 1..3, j in 1..3]) <= 1
    );

% 3. Every pair of elements from 1..n appears in exactly one triple
constraint
    forall(a in 1..n-1, b in a+1..n) (
        sum([bool2int(
            (sets[t,1] == a /\ sets[t,2] == b) \/
            (sets[t,1] == a /\ sets[t,3] == b) \/
            (sets[t,2] == a /\ sets[t,3] == b) \/
            (sets[t,1] == b /\ sets[t,2] == a) \/
            (sets[t,1] == b /\ sets[t,3] == a) \/
            (sets[t,2] == b /\ sets[t,3] == a)
        ) | t in 1..num_triples]) == 1
    );

solve satisfy;

output [
    "{",
    "\"sets\": [",
    join(",", [
        "[" ++ join(",", [show(sets[t,i]) | i in 1..3]) ++ "]"
        | t in 1..num_triples
    ]),
    "]",
    "}"
];
