% Input data
int: n = 12;

% Check that n is a multiple of 4 and n >= 8
constraint n mod 4 = 0 /\ n >= 8;

% The numbers to partition
set of int: NUMS = 1..n;
int: half = n div 2;

% Decision variables: x[i] = 1 if i in A, 0 if i in B
array[NUMS] of var 0..1: x;

% Constraints
% Each set has half the numbers
constraint sum(i in NUMS)(x[i]) = half;

% Sums of numbers are equal
constraint sum(i in NUMS)(i * x[i]) = sum(i in NUMS)(i * (1 - x[i]));

% Sums of squares are equal
constraint sum(i in NUMS)(i * i * x[i]) = sum(i in NUMS)(i * i * (1 - x[i]));

% Define sets A and B
array[1..half] of var NUMS: A;
array[1..half] of var NUMS: B;

% Link A and B to x
constraint
    forall(j in 1..half)(
        exists(i in NUMS)(x[i] = 1 /\ A[j] = i)
    ) /\
    forall(j in 1..half)(
        exists(i in NUMS)(x[i] = 0 /\ B[j] = i)
    );

% All elements in A and B are distinct and cover NUMS
constraint all_different(A) /\ all_different(B);
constraint
    forall(i in NUMS)(
        (x[i] = 1 /\ exists(j in 1..half)(A[j] = i)) \/
        (x[i] = 0 /\ exists(j in 1..half)(B[j] = i))
    );

solve satisfy;

output [
    "{",
    "\"A\": [" ++ join(",", [show(A[j]) | j in 1..half]) ++ "], ",
    "\"B\": [" ++ join(",", [show(B[j]) | j in 1..half]) ++ "]",
    "}"
];
