% Diamond-free Degree Sequences for N=10
include "globals.mzn";

int: N = 10;

% Decision variables
array[1..N, 1..N] of var 0..1: matrix; % adjacency matrix
array[1..N] of var 1..N-1: deg;        % degree sequence (no isolated vertices, max degree N-1)

% 1. Simple undirected graph: no loops, symmetric adjacency
constraint
    forall(i in 1..N) (
        matrix[i,i] = 0
    ) /\
    forall(i, j in 1..N where i < j) (
        matrix[i,j] = matrix[j,i]
    );

% 2. Degree sequence: deg[i] = sum of row i
constraint
    forall(i in 1..N) (
        deg[i] = sum(j in 1..N)(matrix[i,j])
    );

% 3. Degree sequence is non-increasing
constraint
    forall(i in 1..N-1) (
        deg[i] >= deg[i+1]
    );

% 4. Each degree > 0 and divisible by 3
constraint
    forall(i in 1..N) (
        deg[i] > 0 /\ deg[i] mod 3 = 0
    );

% 5. Sum of degrees is divisible by 12 (i.e., |E| is divisible by 6)
constraint
    sum(i in 1..N)(deg[i]) mod 12 = 0;

% 6. Diamond-free: For every set of 4 vertices, at most 4 edges among them
set of int: V = 1..N;
array[1..4] of int: idxs; % for tuple generation

constraint
    forall(i1 in 1..N-3, i2 in i1+1..N-2, i3 in i2+1..N-1, i4 in i3+1..N) (
        let {
            set of int: S = {i1, i2, i3, i4},
            array[1..4] of int: vs = [i1, i2, i3, i4]
        } in
        sum(a in 1..4, b in a+1..4)(matrix[vs[a], vs[b]]) <= 4
    );

% 7. Only output one representative per degree sequence (break symmetries)
%    (This is handled by the non-increasing degree constraint.)

solve satisfy;

output [
    "{",
    "\"matrix\": [",
    join(",", [ "[" ++ join(",", [show(matrix[i,j]) | j in 1..N]) ++ "]" | i in 1..N ]),
    "]",
    "}"
];
```

