% Graceful Graphs Problem
% Given: m edges, n nodes, and the edge list 'graph'
% Find: a graceful labelling of the nodes and the induced edge labels

include "globals.mzn";

% Input data
int: m = 16; % number of edges
int: n = 8;  % number of nodes
array[1..m, 1..2] of int: graph = 
    [| 0, 1 | 0, 2 | 0, 3 | 1, 2 | 1, 3 | 2, 3 |
       4, 5 | 4, 6 | 4, 7 | 5, 6 | 5, 7 | 6, 7 |
       0, 4 | 1, 5 | 2, 6 | 3, 7 |];

% The node labels: unique values from 0..m
array[0..n-1] of var 0..m: nodes;

% The edge labels: for each edge, the absolute difference of its node labels
array[1..m] of var 1..m: edges;

% Constraints

% Node labels are all different
constraint all_different(nodes);

% Edge labels are all different
constraint all_different(edges);

% For each edge, set the edge label as the absolute difference of its node labels
constraint
    forall(e in 1..m) (
        let {
            var int: u = nodes[graph[e,1]],
            var int: v = nodes[graph[e,2]]
        } in
            edges[e] = abs(u - v)
    );

solve satisfy;

output [
    "{",
    "\"nodes\": [" ++ join(",", [show(nodes[i]) | i in 0..n-1]) ++ "],",
    "\"edges\": [" ++ join(",", [show(edges[e]) | e in 1..m]) ++ "]",
    "}"
];
```

