% The product of the ages is 36
% The sum of the ages is ambiguous (i.e., there are at least two different triples with the same sum)
% There is a unique oldest son (i.e., not all ages are equal, and there is a unique maximum)

% Possible ages (since 1*1*36=36, and 36 is not too large, we can bound ages to 1..36)
set of int: Ages = 1..36;

% Decision variables: ages of the three sons
array[1..3] of var Ages: A;

% Order: A1 >= A2 >= A3
var int: A1;
var int: A2;
var int: A3;

constraint
    % Assign variables in order
    A1 = A[1] /\
    A2 = A[2] /\
    A3 = A[3] /\
    A1 >= A2 /\
    A2 >= A3;

% The product of the ages is 36
constraint
    A1 * A2 * A3 = 36;

% All ages are at least 1
constraint
    forall(i in 1..3)(A[i] >= 1);

% There is a unique oldest son (i.e., A1 > A2)
constraint
    A1 > A2;

% Now, we need to ensure that the sum of the ages is ambiguous:
% That is, there is at least one other triple (possibly with different ages) with the same sum and product 36,
% and also with a unique oldest son.

% Let's enumerate all possible triples (x, y, z) with x >= y >= z >= 1, x*y*z = 36, and x > y
array[1..N] of array[1..3] of int: all_triples =
    [ [x, y, z] |
        x in Ages, y in 1..x, z in 1..y,
        x * y * z == 36,
        x > y
    ];
int: N = length([1 | x in Ages, y in 1..x, z in 1..y where x * y * z == 36 /\ x > y]);

% For each triple, compute its sum
array[1..N] of int: all_sums = [sum(t) | t in all_triples];

% The sum of our solution
var int: sumA = A1 + A2 + A3;

% The sum must appear at least twice in all_sums (i.e., ambiguous sum)
constraint
    sum([bool2int(all_sums[i] == sumA) | i in 1..N]) >= 2;

solve satisfy;

output [
    "{",
    "\"A1\": ", show(A1), ", ",
    "\"A2\": ", show(A2), ", ",
    "\"A3\": ", show(A3),
    "}"
];
```

