% Include the standard global constraints library
include "globals.mzn";

% Decision variables: my age (m) and husband's age (h)
% Let's assume reasonable age bounds (e.g., 1 to 120)
var 1..120: m;
var 1..120: h;

% The four operations to be applied in some order:
% +2, /8, -3, *7

% There are 24 possible orders (4! = 24)
% We'll enumerate all possible permutations

% Helper: apply a single operation
function var int: apply_op(var int: x, int: op) =
    if op == 1 then x + 2
    elseif op == 2 then x div 8
    elseif op == 3 then x - 3
    else x * 7
    endif;

% All permutations of [1,2,3,4] (representing the 4 operations)
array[1..24, 1..4] of int: perms = [
    % 1: +2, 2: /8, 3: -3, 4: *7
    | 1,2,3,4 | 1,2,4,3 | 1,3,2,4 | 1,3,4,2 | 1,4,2,3 | 1,4,3,2
    | 2,1,3,4 | 2,1,4,3 | 2,3,1,4 | 2,3,4,1 | 2,4,1,3 | 2,4,3,1
    | 3,1,2,4 | 3,1,4,2 | 3,2,1,4 | 3,2,4,1 | 3,4,1,2 | 3,4,2,1
    | 4,1,2,3 | 4,1,3,2 | 4,2,1,3 | 4,2,3,1 | 4,3,1,2 | 4,3,2,1
];

% For each permutation, define the result of applying the operations in order
array[1..24] of var int: m_to_h;
array[1..24] of var int: h_to_m;

% For each permutation, compute the result of applying the operations in order
constraint
    forall(p in 1..24) (
        let {
            var int: s1 = apply_op(m, perms[p,1]),
            var int: s2 = apply_op(s1, perms[p,2]),
            var int: s3 = apply_op(s2, perms[p,3]),
            var int: s4 = apply_op(s3, perms[p,4])
        } in
            m_to_h[p] = s4
    ) /\
    forall(p in 1..24) (
        let {
            var int: t1 = apply_op(h, perms[p,1]),
            var int: t2 = apply_op(t1, perms[p,2]),
            var int: t3 = apply_op(t2, perms[p,3]),
            var int: t4 = apply_op(t3, perms[p,4])
        } in
            h_to_m[p] = t4
    );

% There must exist two different permutations p1 and p2 such that:
% - Applying p1 to m gives h
% - Applying p2 to h gives m
% - p1 != p2
var 1..24: p1;
var 1..24: p2;

constraint p1 != p2;
constraint m_to_h[p1] = h;
constraint h_to_m[p2] = m;

solve satisfy;

output [
    "{",
    "\"m\": ", show(m), ", ",
    "\"h\": ", show(h),
    "}"
];
