array[Allergies] of string: allergy_names = ["eggs", "mold", "nuts", "ragweed"];

% Surnames: 0=Baxter, 1=Lemon, 2=Malone, 3=Fleet
set of int: Surnames = 0..3;
array[Surnames] of string: surname_names = ["baxter", "lemon", "malone", "fleet"];

% Decision variables
array[0..3] of var Allergies: allergy; % allergy[i] = allergy of friend i
array[0..3] of var Surnames: surname;  % surname[i] = surname of friend i

