% There are 5 bales
int: n_bales = 5;

% The 10 pairwise sums, sorted
array[1..10] of int: pair_sums = [80, 82, 83, 84, 85, 86, 87, 88, 90, 91];

% Decision variables: weights of the 5 bales, in increasing order
array[1..n_bales] of var 1..100: bales;

% The 10 possible pairs (i < j)
set of int: PAIR_IDX = 1..10;
array[PAIR_IDX] of var 2..200: all_pairs;

% Generate all pairs (i, j) with i < j
array[1..10] of int: pair_i = [1,1,1,1,1,2,2,2,3,3];
array[1..10] of int: pair_j = [2,3,4,5,2,3,4,5,4,5];

% Constraint: bales are in increasing order (to break symmetry)
constraint forall(i in 1..n_bales-1)(bales[i] <= bales[i+1]);

% all_pairs[k] = bales[pair_i[k]] + bales[pair_j[k]]
constraint forall(k in PAIR_IDX)(
    all_pairs[k] = bales[pair_i[k]] + bales[pair_j[k]]
);

% The multiset of all_pairs must match the given pair_sums (sorted)
constraint
    forall(k in PAIR_IDX)(
        % After sorting all_pairs, it must match pair_sums
        % So, we use a permutation variable to match all_pairs to pair_sums
        exists(p in PAIR_IDX)(all_pairs[p] = pair_sums[k])
    ) /\
    forall(k in PAIR_IDX)(
        exists(p in PAIR_IDX)(pair_sums[p] = all_pairs[k])
    );

solve satisfy;

output [
    "{",
    "\"bales\": [" ++ join(",", [show(bales[i]) | i in 1..n_bales]) ++ "]",
    "}"
];
