array[0..5] of var 0..5: x;

% All guests must be seated exactly once
constraint all_different(x);

% For each pair of adjacent seats (table is circular), define a conflict if the two guests are not allowed to sit next to each other
array[0..5] of var 0..1: conflict;

constraint
    forall(i in 0..5) (
        let {
            var int: left = x[i],
            var int: right = x[(i+1) mod n]
        } in
        % There is a conflict if right is not in allowed_neighbors[left] or left is not in allowed_neighbors[right]
        conflict[i] = bool2int(
            not (right in allowed_neighbors[left] /\ left in allowed_neighbors[right])
        )
    );

% Objective: minimize total conflicts
var int: total_conflict = sum(i in 0..5)(conflict[i]);

solve minimize total_conflict;

output [
    "{",
    "\"x\": [" ++ join(",", [show(x[i]) | i in 0..5]) ++ "]",
    "}"
];
