include "globals.mzn";

% Number of dice and faces per die
int: num_dice = 5;
int: faces_per_die = 7; % 7 is the minimal known solution

% The dice: dice[d, f] is the value of face f on die d
array[1..num_dice, 1..faces_per_die] of var 1..faces_per_die * num_dice: dice;

% The "beats" relationships as pairs (winner, loser)
set of int: D = 1..num_dice;
array[1..10, 1..2] of int: beats = 
  [| 1,3 | % Rock(1) crushes Scissors(3)
     1,4 | % Rock(1) crushes Lizard(4)
     2,1 | % Paper(2) covers Rock(1)
     2,5 | % Paper(2) disproves Spock(5)
     3,2 | % Scissors(3) cuts Paper(2)
     3,4 | % Scissors(3) decapitate Lizard(4)
     4,2 | % Lizard(4) eats Paper(2)
     4,5 | % Lizard(4) poisons Spock(5)
     5,1 | % Spock(5) vaporizes Rock(1)
     5,3 | % Spock(5) smashes Scissors(3)
  |];

% For each pair of dice, compute the number of times die i beats die j
array[D, D] of var 0..faces_per_die*faces_per_die: beats_count;

constraint
  forall(i in D, j in D where i != j) (
    beats_count[i,j] = sum([bool2int(dice[i,fi] > dice[j,fj]) | fi in 1..faces_per_die, fj in 1..faces_per_die])
  );

% For each "beats" relationship, require that the winner beats the loser in more than half of the face-offs
constraint
  forall(r in 1..10) (
    beats_count[beats[r,1], beats[r,2]] > faces_per_die * faces_per_die div 2
  );

% For all other pairs (not in "beats"), the reverse must be true
constraint
  forall(i in D, j in D where i != j /\ not exists(r in 1..10)(beats[r,1]=i /\ beats[r,2]=j)) (
    beats_count[i,j] < faces_per_die * faces_per_die div 2
  );

% Optional: symmetry breaking (sort dice lexicographically)
constraint
  forall(d in 1..num_dice-1) (
    lex_lesseq([dice[d,f] | f in 1..faces_per_die], [dice[d+1,f] | f in 1..faces_per_die])
  );

solve satisfy;

output [
  "{",
  "\"dice\": [",
  join(",", [ "[" ++ join(",", [show(dice[d,f]) | f in 1..faces_per_die]) ++ "]" | d in 1..num_dice ]),
  "]",
  "}"
];
```

