% Bachet's weighing problem (1612)
% Find four integer weights that sum to 40 and can weigh every integer 1..40
% using a balance scale (weights can go on either side).

include "globals.mzn";

int: N = 4; % number of pieces
int: TOTAL = 40; % total weight

% Decision variables: the weights of the four pieces, sorted in increasing order
array[1..N] of var 1..TOTAL: weights;

% The weights must be in increasing order to avoid symmetric solutions
constraint increasing(weights);

% The sum of the weights must be 40
constraint sum(weights) == TOTAL;

% For each target weight from 1 to 40, we must be able to achieve it
% by putting each weight on the left pan (+1), right pan (-1), or not used (0)
% That is, for each t in 1..40, there exists an assignment of {-1,0,1} to the 4 weights
% such that sum(signs[i] * weights[i]) = t

% For each t in 1..40, introduce an existential quantification over the 3^4 possible sign assignments
% We'll use an array of all possible sign assignments

set of int: SIGNS = {-1,0,1};

% Generate all possible sign assignments for 4 weights
array[1..N, 1..3^N] of int: all_signs = 
  array2d(1..N, 1..3^N, 
    [ ( ( ( ( (i-1) div (3^(N-j)) ) mod 3 ) - 1 ) ) | j in 1..N, i in 1..3^N ]
  );

% For each t in 1..40, there must exist a sign assignment s such that sum(signs[i] * weights[i]) = t
constraint
  forall(t in 1..TOTAL) (
    exists(s in 1..3^N) (
      sum(i in 1..N)(all_signs[i,s] * weights[i]) == t
    )
  );

solve satisfy;

output [
    "{",
    "\"weights\": [" ++ join(",", [show(weights[i]) | i in 1..N]) ++ "]",
    "}"
];
```

