% Number of devices
int: N = 8;

% Device names for reference (A=1, B=2, ..., H=8)
set of int: Devices = 1..N;

% List of connections: (device1, device2, number_of_cables)
% Devices are mapped as: A=1, B=2, C=3, D=4, E=5, F=6, G=7, H=8
int: num_connections = 8;
array[1..num_connections] of int: conn_from = [1, 1, 2, 3, 3, 3, 4, 7];
array[1..num_connections] of int: conn_to   = [8, 5, 6, 7, 4, 5, 8, 8];
array[1..num_connections] of int: conn_cables = [1, 2, 4, 1, 1, 1, 3, 1];

% Decision variables: position[i] is the rack position (1..8) of device i
array[Devices] of var 1..N: position;

% All devices must be placed in different positions
constraint all_different(position);

% For each connection, compute the cable length as the distance between devices
array[1..num_connections] of var 0..N-1: cable_lengths;
constraint
    forall(i in 1..num_connections) (
        cable_lengths[i] = abs(position[conn_from[i]] - position[conn_to[i]])
    );

% Total cable length is the sum over all connections, weighted by number of cables
var int: final_sum = sum(i in 1..num_connections)(conn_cables[i] * cable_lengths[i]);

solve minimize final_sum;

output [
    "{",
    "\"final_sum\": ", show(final_sum),
    "}"
];
