array[1..N] of var 1..n: pos_row;
array[1..N] of var 1..n: pos_col;

% Link x and pos_row/pos_col
constraint
    forall(i in 1..n, j in 1..n) (
        let { var int: k = x[i,j] } in
            pos_row[k] = i /\ pos_col[k] = j
    );

% All numbers 1..N must appear exactly once
constraint all_different([x[i,j] | i in 1..n, j in 1..n]);

% Movement constraints
constraint
    forall(k in 1..N-1) (
        let {
            var int: dr = abs(pos_row[k+1] - pos_row[k]),
            var int: dc = abs(pos_col[k+1] - pos_col[k])
        } in
        (
            % Type I: horizontal or vertical, exactly 3 squares away
            ((dr = 3 /\ dc = 0) \/ (dr = 0 /\ dc = 3))
            \/
            % Type II: diagonal, exactly 2 squares away
            (dr = 2 /\ dc = 2)
        )
    );

solve satisfy;

output [
    "{\n\"x\": [",
    join(",\n", [
        "[" ++ join(",", [show(x[i,j]) | j in 1..n]) ++ "]"
        | i in 1..n
    ]),
    "]\n}"
];
