include "globals.mzn";

% Input data
int: num_warehouses = 4;
int: num_regions = 3;
array[1..num_warehouses] of string: warehouse_s = ["New York", "Los Angeles", "Chicago", "Atlanta"];
array[1..num_warehouses] of int: fixed_costs = [400, 500, 300, 150];
int: max_shipping = 100;
array[1..num_regions] of int: demands = [80, 70, 40];
array[1..num_warehouses, 1..num_regions] of int: shipping_costs = 
    [| 20, 40, 50,
       48, 15, 26,
       26, 35, 18,
       24, 50, 35 |];

% Decision variables
array[1..num_warehouses] of var 0..1: open_warehouse; % 1 if warehouse is open, 0 otherwise
array[1..num_warehouses, 1..num_regions] of var 0..max_shipping: ships; % units shipped from warehouse i to region j

% Constraints

% 1. If New York is open, Los Angeles must also be open
constraint open_warehouse[1] <= open_warehouse[2];

% 2. No more than three warehouses can be operational
constraint sum(open_warehouse) <= 3;

% 3. Either Atlanta or Los Angeles must be open
constraint open_warehouse[2] + open_warehouse[4] >= 1;

% 4. Each region's demand must be met exactly
constraint forall(r in 1..num_regions)(
    sum([ships[w, r] | w in 1..num_warehouses]) == demands[r]
);

% 5. Each warehouse can only ship if it is open, and cannot exceed max shipping
constraint forall(w in 1..num_warehouses)(
    sum([ships[w, r] | r in 1..num_regions]) <= max_shipping * open_warehouse[w]
);

% 6. No shipments from closed warehouses
constraint forall(w in 1..num_warehouses, r in 1..num_regions)(
    ships[w, r] <= max_shipping * open_warehouse[w]
);

% Objective: Minimize total cost (fixed + shipping)
var int: total_cost = 
    sum(w in 1..num_warehouses)(fixed_costs[w] * open_warehouse[w]) +
    sum(w in 1..num_warehouses, r in 1..num_regions)(shipping_costs[w, r] * ships[w, r]);

solve minimize total_cost;

output [
    "{",
    "\"total_cost\": ", show(total_cost), ", ",
    "\"open_warehouse\": [", join(",", [show(open_warehouse[w]) | w in 1..num_warehouses]), "], ",
    "\"ships\": [",
        join(",", [
            "[" ++ join(",", [show(ships[w, r]) | r in 1..num_regions]) ++ "]"
            | w in 1..num_warehouses
        ]),
    "]",
    "}"
];
```

